using System;

namespace SysopTV.Tray
{
    // Characters 32 to 127. Each glyph: rows of (width + 7) / 8 bytes, MSB is the left pixel.
    internal sealed class TftFont
    {
        internal readonly int Height;
        internal readonly byte[] Widths;
        private readonly int[] offsets;
        private readonly byte[] data;

        internal TftFont(int height, byte[] widths, int[] offsets, string base64)
        {
            Height = height;
            Widths = widths;
            this.offsets = offsets;
            data = Convert.FromBase64String(base64);
        }

        internal int Width(char c)
        {
            return c >= 32 && c < 128 ? Widths[c - 32] : 0;
        }

        internal bool Pixel(char c, int x, int y)
        {
            if (c < 32 || c >= 128)
            {
                return false;
            }
            int w = Widths[c - 32];
            int rb = (w + 7) / 8;
            return (data[offsets[c - 32] + y * rb + x / 8] & (0x80 >> (x % 8))) != 0;
        }
    }

